<script setup>
import {ref,computed,onMounted,onUnmounted,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {get,post,patch,put,del,message} from '../services/api.js';import {useAuth,useUi} from '../stores/index.js';import ConfirmDialog from '../components/ConfirmDialog.vue';import StatChart from '../components/StatChart.vue';import Icon from '../components/common/Icon.vue';import DashShell from '../components/layout/DashShell.vue';
const router=useRouter(),route=useRoute(),auth=useAuth(),ui=useUi(),summary=ref({}),rows=ref([]),meta=ref({}),error=ref(''),busy=ref(false),tab=ref('Restaurants'),charts=ref({}),settings=ref({banner:'',maintenance:false,bannerExpiresAt:''}),deleting=ref(null),reviews=ref([]),reports=ref([]),suggestions=ref([]),userForm=ref({name:'',email:'',password:'',role:'moderator'}),importText=ref(''),importResult=ref(null),filter=ref(''),showUser=ref(false),query=ref(''),acting=ref(false),ask=ref(null),userTouched=ref(false),importErr=ref('');const owner=computed(()=>route.path.startsWith('/owner'));const tabs=computed(()=>owner.value?['Restaurants','Reviews','Messages','Analytics','Notifications']:auth.user?.role==='moderator'?['Restaurants','Trash','Claims','Moderation','Reviews','Logs','Statistics']:['Restaurants','Trash','Claims','Owners','Users','Suggestions','Moderation','Messages','Subscribers','Reviews','Logs','Login history','Statistics','Settings','Import / Export','Data quality']);const title=computed(()=>owner.value?'Restaurant owner dashboard':'Admin dashboard');
const endpoints={'Restaurants':'/admin/restaurants','Trash':'/admin/restaurants?trash=true','Claims':'/claims','Owners':'/admin/users','Users':'/admin/users','Messages':'/contact','Subscribers':'/admin/subscribers','Reviews':'/admin/reviews','Logs':'/admin/logs','Login history':'/admin/login-history','Data quality':'/admin/quality-report','Notifications':'/notifications'};
let loadVersion=0,disposed=false,refreshTimer,countTimer,countVersion=0,countBusy=false;
const lastUpdated=ref(null),countsUpdated=ref(null),countError=ref('');
async function refreshCounts(){
 if(disposed||document.hidden||countBusy)return;
 countBusy=true;const version=++countVersion,isOwner=owner.value;
 try{
  const result=await get(isOwner?'/owner/stats':'/admin/stats/summary',{_refresh:Date.now()});
  if(!disposed&&version===countVersion&&isOwner===owner.value){summary.value=result.data;countsUpdated.value=new Date();countError.value='';}
 }catch(e){if(!disposed&&version===countVersion)countError.value='Counts could not refresh. Retrying automatically.';}
 finally{countBusy=false;}
}
function refreshVisible(){refreshCounts();autoRefresh();}
async function load({silent=false}={}){
 const version=++loadVersion,currentTab=tab.value,isOwner=owner.value,currentFilter=filter.value;
 if(!silent)busy.value=true;
 error.value='';
 const fresh=(url,params={})=>get(url,{...params,_refresh:Date.now()});
 try{
  await auth.load();
  await refreshCounts();
  let nextRows=[],nextMeta={},nextCharts={},nextReviews=[],nextReports=[],nextSuggestions=[],nextSettings;
  const restricted=isOwner&&!auth.canManage&&['Restaurants','Reviews','Messages'].includes(currentTab);
  if(!restricted){
   if(['Statistics','Analytics'].includes(currentTab)){
    const grouped=await Promise.all(['borough','cuisine','country'].map(key=>fresh('/restaurants/stats/by-'+key)));
    ['borough','cuisine','country'].forEach((key,index)=>nextCharts[key]=grouped[index].data);
    if(!isOwner)nextReviews=(await fresh('/admin/stats/reviews')).data;
   }else if(currentTab==='Settings')nextSettings=(await fresh('/settings')).data;
   else if(currentTab==='Moderation'){
    const a=await Promise.all([fresh('/admin/reviews'),fresh('/reports'),fresh('/suggestions')]);
    nextReviews=a[0].data;nextReports=a[1].data;nextSuggestions=a[2].data;
   }else if(currentTab!=='Import / Export'){
    const endpoint=isOwner&&['Restaurants','Reviews','Messages'].includes(currentTab)?'/owner/'+currentTab.toLowerCase():endpoints[currentTab];
    if(endpoint){const x=await fresh(endpoint,{limit:100,status:currentFilter||undefined,role:currentTab==='Owners'?'owner':undefined});nextRows=x.data;nextMeta=x.meta||{};}
   }
  }
  if(disposed||version!==loadVersion)return false;
  rows.value=nextRows;meta.value=nextMeta;charts.value=nextCharts;reviews.value=nextReviews;reports.value=nextReports;suggestions.value=nextSuggestions;
  if(nextSettings)settings.value={...settings.value,...nextSettings};
  lastUpdated.value=new Date();return true;
 }catch(e){if(!disposed&&version===loadVersion)error.value=message(e);return false;}
 finally{if(!disposed&&version===loadVersion)busy.value=false;}
}
function autoRefresh(){
 if(document.hidden||busy.value||acting.value||showUser.value||ask.value||deleting.value||['Settings','Import / Export'].includes(tab.value)||document.activeElement?.matches('input,textarea,select'))return;
 load({silent:true});
}
async function action(fn,msg='Changes saved.'){if(acting.value)return false;acting.value=true;try{await fn();ui.toast(msg);const refreshed=await load();if(!refreshed)ui.toast('The action was saved, but the dashboard could not refresh. Use Refresh dashboard.','error');return true;}catch(e){ui.toast(message(e),'error');return false;}finally{acting.value=false;}}
const shownRows=computed(()=>{const t=query.value.trim().toLowerCase();return t?rows.value.filter(r=>JSON.stringify(r).toLowerCase().includes(t)):rows.value;});const searchable=computed(()=>!['Settings','Statistics','Analytics','Import / Export','Moderation'].includes(tab.value));
async function confirmed(){const a=ask.value;if(!a)return;const ok=await action(a.fn,a.done);if(ok)ask.value=null;}
const statLabel=k=>({approved:'Approved listings',pending:'Pending approval',deleted:'In trash',cuisines:'Cuisines',owners:'Owners',reviews:'Reviews',messages:'Messages',subscribers:'Subscribers',pendingRequests:'Pending requests',pendingOwners:'Pending owners',approvedOwners:'Approved owners',users:'Total users',rejected:'Rejected listings',unreadNotifications:'Unread notifications',claims:'Pending claims',restaurantSuggestions:'Restaurant suggestions'}[k]||k.replace(/([A-Z])/g,' $1').replace(/^./,c=>c.toUpperCase()));
const userErr=computed(()=>({name:userTouched.value&&!userForm.value.name.trim()?'Enter a name.':'',email:userTouched.value&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(userForm.value.email)?'Enter an email address like name@example.com.':'',password:userTouched.value&&userForm.value.password.length<8?'Use at least 8 characters.':''}));
function chosenFromPath(){const key=route.path.split('/')[2]||'';const map={restaurants:'Restaurants',trash:'Trash',claims:'Claims',owners:'Owners',users:'Users',moderation:'Moderation',logs:'Logs','login-history':'Login history',stats:'Statistics',settings:'Settings',reviews:'Reviews',messages:'Messages',analytics:'Analytics',notifications:'Notifications',subscribers:'Subscribers','import-export':'Import / Export',quality:'Data quality'};tab.value=map[key]||'Restaurants';}
function choose(x){filter.value='';query.value='';const slugs={'Restaurants':'restaurants','Trash':'trash','Claims':'claims','Owners':'owners','Users':'users','Suggestions':'suggestions','Moderation':'moderation','Messages':'messages','Subscribers':'subscribers','Reviews':'reviews','Logs':'logs','Login history':'login-history','Statistics':'stats','Analytics':'analytics','Notifications':'notifications','Settings':'settings','Import / Export':'import-export','Data quality':'quality'};router.push((owner.value?'/owner/':'/admin/')+slugs[x]);}function columns(row){return Object.entries(row).filter(([k])=>!['_id','__v','updatedAt','passwordHash','tokenVersion'].includes(k));}function readable(value){if(value===null||value===undefined)return '—';if(typeof value==='object')return JSON.stringify(value);return String(value);}async function remove(){const r=deleting.value;if(await action(()=>del('/restaurants/'+r._id),'Restaurant moved to Trash.'))deleting.value=null;}async function exportData(format){try{if(format==='csv'){const {api}=await import('../services/api.js');const r=await api.get('/admin/restaurants/export',{params:{format},responseType:'blob'});download(r.data,'restaurants.csv');}else{const r=await get('/admin/restaurants/export');download(new Blob([JSON.stringify(r.data,null,2)],{type:'application/json'}),'restaurants.json');}}catch(e){ui.toast(message(e),'error');}}function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url);}async function importData(){importErr.value='';try{const records=JSON.parse(importText.value);if(!Array.isArray(records)){importErr.value='The JSON must be an array of restaurant records, like [ {...}, {...} ].';return;}importResult.value=(await post('/admin/restaurants/import',{records})).data;await load();}catch(e){if(e instanceof SyntaxError)importErr.value='That is not valid JSON. Check for a missing comma or bracket.';else ui.toast(message(e),'error');}}async function userCreate(){userTouched.value=true;if(Object.values(userErr.value).some(Boolean))return;if(await action(()=>post('/admin/users',userForm.value),'Account created.')){showUser.value=false;userTouched.value=false;userForm.value={name:'',email:'',password:'',role:'moderator'};}}
const tabIcons={Restaurants:'utensils',Trash:'trash',Claims:'shield',Owners:'user',Users:'user',Suggestions:'book',Moderation:'shield',Messages:'mail',Subscribers:'mail',Reviews:'star',Logs:'book','Login history':'clock',Statistics:'trending',Analytics:'trending',Settings:'sliders','Import / Export':'table','Data quality':'check',Notifications:'calendar'};
const navItems=computed(()=>tabs.value.map(label=>({label,icon:tabIcons[label]||'grid',badge:label==='Notifications'?(summary.value.unreadNotifications||''):''})));
const adminKeys=['restaurants','approved','pending','deleted','cuisines','users','owners','pendingOwners','approvedOwners','claims','restaurantSuggestions','reviews','messages','subscribers','pendingRequests'];
const stripStats=computed(()=>Object.entries(summary.value).filter(([k])=>owner.value?true:adminKeys.includes(k)).map(([k,v])=>({label:statLabel(k),value:v})));
const profileStats=computed(()=>{const m=summary.value,pick=owner.value?['restaurants','views','saves']:['approved','pending','reviews'];return pick.filter(k=>m[k]!==undefined).map(k=>({label:statLabel(k).replace('Approved listings','Approved').replace('Pending approval','Pending'),value:m[k]}));});
const breakdown=computed(()=>{const m=summary.value;if(owner.value)return m.restaurants?[{label:'Approved',value:m.approved||0},{label:'Pending',value:m.pending||0},{label:'Rejected',value:m.rejected||0}]:[];return m.approved!==undefined?[{label:'Approved',value:m.approved||0},{label:'Pending',value:m.pending||0},{label:'In trash',value:m.deleted||0}]:[];});
async function logoutNow(){await auth.logout();router.push('/logged-out');}
onMounted(()=>{chosenFromPath();load();refreshTimer=setInterval(autoRefresh,15000);countTimer=setInterval(refreshCounts,5000);window.addEventListener('focus',refreshVisible);document.addEventListener('visibilitychange',refreshVisible);});onUnmounted(()=>{disposed=true;++loadVersion;clearInterval(refreshTimer);clearInterval(countTimer);++countVersion;window.removeEventListener('focus',refreshVisible);document.removeEventListener('visibilitychange',refreshVisible);});watch(()=>route.path,()=>{chosenFromPath();load();});
</script>
<template><DashShell :class="{acting}" :title="title" subtitle="Manage listings, community feedback and account activity." :nav="navItems" :active="tab" :stats="stripStats" :profile-stats="profileStats" :role-label="owner?'Owner workspace':'Admin workspace'" :add-link="auth.canManage" :breakdown="breakdown" breakdown-title="Listings by approval" @select="choose" @logout="logoutNow"><section v-if="owner" class="notice" role="status"><h2>Owner application: {{auth.user?.ownerProfile?.verificationStatus||'pending'}}</h2><p v-if="!auth.user?.emailVerified">Verify your email before managing restaurant listings. <RouterLink to="/verify-email">Verify email</RouterLink></p><p v-if="auth.user?.ownerProfile?.verificationStatus==='pending'">Your application is awaiting administrator review. Listing management becomes available after both email verification and approval.</p><p v-else-if="auth.user?.ownerProfile?.verificationStatus==='rejected'">Your application was rejected: {{auth.user.ownerProfile.rejectionReason||'Contact an administrator for details.'}}</p><p v-else>Approved. You can add and manage your own listings once your email is verified.</p></section><RouterLink v-if="auth.user?.role==='admin'" to="/admin/suggestions" class="btn secondary">Review restaurant suggestions</RouterLink><div class="row" style="margin:16px 0"><button type="button" class="secondary" :disabled="busy||acting" @click="load()">{{busy?'Refreshing…':'Refresh dashboard'}}</button><span v-if="lastUpdated" class="small muted" role="status">Updated {{lastUpdated.toLocaleTimeString()}}</span></div><p class="small muted" role="status">Counts update every 5 seconds<span v-if="countsUpdated"> · Last checked {{countsUpdated.toLocaleTimeString()}}</span>.</p><p v-if="countError" class="error-box" role="alert">{{countError}}</p><p v-if="error" class="error-box" role="alert">{{error}}</p><div v-if="searchable&&!busy&&rows.length>2" class="toolbar"><div class="search-wrap"><label class="sr-only" for="dash-search">Search this list</label><input id="dash-search" v-model="query" type="search" :placeholder="'Search '+tab.toLowerCase()" autocomplete="off"><button v-if="query" type="button" class="clear-x" aria-label="Clear search" @click="query=''"><Icon name="x" :size="16"/></button></div><span class="meta-count" role="status" aria-live="polite">{{shownRows.length}} of {{rows.length}}</span></div><div v-if="busy" class="skeleton" aria-busy="true"></div><Transition v-else name="tab" mode="out-in" appear><div :key="tab" class="tab-panel" role="tabpanel"><section v-if="tab==='Settings'" class="card pad reading"><form @submit.prevent="action(()=>put('/settings',settings),'Settings saved.')" class="stack"><h2>Site settings</h2><label for="site-banner">Announcement banner</label><textarea id="site-banner" v-model="settings.banner" maxlength="300"></textarea><span class="char-count">{{(settings.banner||'').length}} / 300</span><label for="banner-expiry">Banner expiry (optional)</label><input id="banner-expiry" v-model="settings.bannerExpiresAt" type="datetime-local"><label><input v-model="settings.maintenance" type="checkbox"> Maintenance mode</label><button :class="{'is-loading':acting}" :disabled="acting"><span>Save settings</span></button></form></section><section v-else-if="tab==='Import / Export'" class="stack"><div class="row"><button @click="exportData('json')">Export JSON</button><button @click="exportData('csv')">Export CSV</button></div><form novalidate @submit.prevent="importData" class="card pad stack"><h2>Import restaurant JSON</h2><p>Paste an array in the seed-file format. Each row is validated and a result is reported. Import upserts by restaurant_id.</p><label for="import-json">Records</label><textarea id="import-json" v-model="importText" style="min-height:220px" :aria-invalid="!!importErr" aria-describedby="import-msg" @input="importErr=''"></textarea><p id="import-msg" v-if="importErr" class="field-msg">{{importErr}}</p><button class="cta" :disabled="!importText.trim()">Validate and import</button></form><pre v-if="importResult" class="card pad" style="overflow:auto">{{JSON.stringify(importResult,null,2)}}</pre></section><section v-else-if="['Statistics','Analytics'].includes(tab)" class="stack"><p v-if="owner" class="muted">Your listing counters appear above. The charts below describe the public collection.</p><div class="grid"><StatChart v-for="key in ['borough','cuisine','country']" :key="key" :title="'Restaurants by '+key" :rows="charts[key]||[]"/></div><div v-if="reviews.length" class="card pad"><h2>Review activity in the last 30 days</h2><p v-for="r in reviews" :key="r._id">{{r._id}} · {{r.count}} reviews · Average {{r.avgRating?.toFixed(1)}}</p></div></section><section v-else-if="tab==='Moderation'" class="stack"><h2>Review moderation</h2><article v-for="r in reviews" :key="r._id" class="card pad"><p><b>{{r.author}}</b> · {{r.status}} · {{r.rating}} stars</p><p>{{r.comment}}</p><div class="row"><button @click="action(()=>patch('/reviews/'+r._id,{status:'published'}))">Publish</button><button class="secondary" @click="action(()=>patch('/reviews/'+r._id,{status:'hidden'}))">Hide</button><button class="cta" @click="ask={title:'Delete this review?',text:'The review will be removed permanently.',fn:()=>del('/reviews/'+r._id),done:'Review deleted.'}">Delete</button></div></article><h2>Reports</h2><article v-for="r in reports" :key="r._id" class="card pad"><p>{{r.type}} · {{r.status}} · {{r.reason}}</p><RouterLink v-if="r.type!=='review'" :to="'/restaurants/'+r.targetId">Open restaurant</RouterLink><div class="row"><button @click="action(()=>patch('/reports/'+r._id,{status:'resolved'}))">Resolve</button><button class="secondary" @click="action(()=>patch('/reports/'+r._id,{status:'dismissed'}))">Dismiss</button></div></article><h2>Suggested edits</h2><article v-for="s in suggestions" :key="s._id" class="card pad"><p>{{s.field}} → {{s.proposedValue}} · {{s.status}}</p><div class="row"><button v-if="s.status==='pending'" @click="action(()=>patch('/restaurants/'+s.restaurant+'/suggestions',{id:s._id,status:'approved'}))">Accept</button><button v-if="s.status==='pending'" class="secondary" @click="action(()=>patch('/restaurants/'+s.restaurant+'/suggestions',{id:s._id,status:'rejected'}))">Reject</button></div></article></section><section v-else-if="['Restaurants','Trash'].includes(tab)"><div v-if="!owner&&tab==='Restaurants'" class="row" style="margin-bottom:20px"><label for="approval-filter">Approval status</label><select id="approval-filter" v-model="filter" style="width:200px" @change="load()"><option value="">All</option><option value="approved">Approved</option><option value="pending">Pending</option><option value="rejected">Rejected</option></select></div><div class="card table-wrap dashboard-restaurants"><table class="dash-table"><thead><tr><th>Name</th><th>Region</th><th>Status</th><th>Approval</th><th>Views / Completion</th><th>Actions</th></tr></thead><tbody><tr v-for="r in shownRows" :key="r._id"><td data-label="Name"><RouterLink :to="'/restaurants/'+r._id">{{r.name}}</RouterLink></td><td data-label="Region">{{r.borough}}</td><td data-label="Status">{{r.status}}</td><td data-label="Approval">{{r.approvalStatus}}</td><td data-label="Views / Completion">{{r.viewCount||0}} / {{r.profileCompletion||0}}%</td><td data-label="Actions"><div class="row restaurant-actions"><template v-if="tab==='Trash'&&auth.user?.role==='admin'"><button @click="action(()=>post('/restaurants/'+r._id+'/restore'))">Restore</button></template><template v-else><RouterLink v-if="auth.canManage" :to="'/restaurants/'+r._id+'/edit'" class="btn secondary small">Edit</RouterLink><button v-if="auth.canManage" class="cta small" @click="deleting=r">Delete</button><button v-if="auth.user?.role==='admin'&&r.approvalStatus!=='approved'" class="small" @click="action(()=>patch('/restaurants/'+r._id+'/approval',{approvalStatus:'approved'}))">Approve</button><button v-if="auth.user?.role==='admin'&&r.approvalStatus==='pending'" class="secondary small" @click="action(()=>patch('/restaurants/'+r._id+'/approval',{approvalStatus:'rejected'}))">Reject</button><select v-if="auth.canManage" :value="r.status" aria-label="Restaurant status" style="width:140px" @change="action(()=>patch('/restaurants/'+r._id+'/status',{status:$event.target.value}))"><option value="open">Open</option><option value="temporarily_closed">Temporarily closed</option><option value="permanently_closed">Permanently closed</option></select></template></div></td></tr></tbody></table></div><p v-if="owner" class="small muted" style="margin-top:20px">Complete your profile: add a story, contact details, hours, an image and a website. Newly added owner listings wait for staff approval.</p></section><section v-else-if="tab==='Claims'" class="stack"><article v-for="c in shownRows" :key="c._id" class="card pad"><h2>{{c.restaurant?.name||'Unavailable listing'}}</h2><p>{{c.user?.name}} · {{c.user?.email}} · {{c.status}}</p><p>{{c.evidenceType}} · {{c.note}}</p><a v-if="/^https?:\/\//.test(c.evidenceUrl||'')" :href="c.evidenceUrl" target="_blank" rel="noopener noreferrer">Review evidence</a><div v-if="c.status==='pending'" class="row" style="margin-top:18px"><button @click="action(()=>patch('/claims/'+c._id,{status:'approved'}))">Approve claim</button><button class="cta" @click="action(()=>patch('/claims/'+c._id,{status:'rejected',reason:'Ownership evidence was not sufficient.'}))">Reject claim</button></div></article></section><section v-else-if="['Users','Owners'].includes(tab)" class="stack"><div class="row"><button :aria-expanded="showUser" @click="showUser=!showUser"><Icon name="plus" :size="16"/>{{showUser?'Close form':'Create account'}}</button></div><form v-if="showUser" novalidate @submit.prevent="userCreate" class="card pad form-grid"><div v-for="key in ['name','email','password']" :key="key" class="field"><label :for="'new-user-'+key" style="text-transform:capitalize">{{key}}</label><input :id="'new-user-'+key" v-model="userForm[key]" :type="key==='password'?'password':key==='email'?'email':'text'" :aria-invalid="!!userErr[key]" :aria-describedby="'new-user-'+key+'-msg'"><p :id="'new-user-'+key+'-msg'" v-if="userErr[key]" class="field-msg">{{userErr[key]}}</p></div><div><label for="new-user-role">Role</label><select id="new-user-role" v-model="userForm.role"><option>customer</option><option>owner</option><option>moderator</option><option>admin</option></select></div><button>Create account</button></form><article v-for="u in shownRows" :key="u._id" class="card pad"><h3>{{u.name}}</h3><p>{{u.email}} · {{u.role}} · {{u.status}}</p><p v-if="u.ownerProfile">{{u.ownerProfile.businessName}} · {{u.ownerProfile.verificationStatus}} · Email {{u.emailVerified?'verified':'unverified'}}</p><div v-if="u.role==='owner'" class="field"><label :for="u._id+'reason'">Rejection reason</label><textarea :id="u._id+'reason'" v-model="u.ownerProfile.rejectionReason" maxlength="1000"></textarea><div class="row"><button :disabled="acting" @click="action(()=>patch('/admin/owners/'+u._id,{status:'approved'}),'Owner account approved.')">Approve owner</button><button class="secondary" :disabled="acting||!u.ownerProfile.rejectionReason?.trim()" @click="action(()=>patch('/admin/owners/'+u._id,{status:'rejected',reason:u.ownerProfile.rejectionReason}),'Owner application rejected.')">Reject owner</button></div></div><div class="row"><button class="secondary" @click="action(()=>patch('/admin/users/'+u._id+'/status',{status:u.status==='active'?'suspended':'active'}))">{{u.status==='active'?'Suspend':'Reactivate'}}</button><select :value="u.role" aria-label="Account role" style="width:170px" @change="action(()=>patch('/admin/users/'+u._id,{role:$event.target.value}))"><option>customer</option><option>owner</option><option>moderator</option><option>admin</option></select></div></article></section><section v-else-if="tab==='Messages'" class="stack"><article v-for="m in shownRows" :key="m._id" class="card pad"><h3>{{m.subject||'Restaurant message'}}</h3><p>{{m.name}} · {{m.email}} · {{m.status}}</p><p>{{m.message}}</p><div class="row"><button class="secondary" @click="action(()=>patch((owner?'/owner/messages/':'/contact/')+m._id,{status:'read'}))">Mark as read</button><a :href="'mailto:'+m.email" class="btn secondary">Reply by email</a><button v-if="!owner" class="cta" @click="ask={title:'Delete this message?',text:'The message will be removed permanently.',fn:()=>del('/contact/'+m._id),done:'Message deleted.'}">Delete</button></div></article></section><section v-else-if="tab==='Reviews'" class="stack"><article v-for="v in shownRows" :key="v._id" class="card pad"><p>{{v.author}} · {{v.rating}} stars · {{v.status}}</p><p>{{v.comment}}</p><RouterLink :to="'/restaurants/'+v.restaurant">Open restaurant</RouterLink><button v-if="!owner" class="cta small" @click="ask={title:'Delete this review?',text:'The review will be removed permanently.',fn:()=>del('/reviews/'+v._id),done:'Review deleted.'}">Delete</button></article></section><section v-else class="stack"><article v-for="r in shownRows" :key="r._id" class="card pad"><dl><template v-for="[key,value] in columns(r)" :key="key"><dt class="muted small">{{key}}</dt><dd style="margin:0 0 12px;overflow-wrap:anywhere">{{readable(value)}}</dd></template></dl><RouterLink v-if="tab==='Notifications'&&r.link" :to="r.link">View notification</RouterLink><button v-if="tab==='Notifications'&&!r.isRead" @click="action(()=>patch('/notifications/'+r._id+'/read'))">Mark read</button></article></section><div v-if="!rows.length&&!['Settings','Statistics','Analytics','Import / Export','Moderation'].includes(tab)" class="empty"><h2>Nothing to show here yet</h2></div><div v-if="query&&rows.length&&!shownRows.length" class="card empty-results"><h2>No matches for “{{query}}”</h2><p class="muted">Try another word.</p><div class="row"><button class="cta" @click="query=''">Clear search</button></div></div><p v-if="meta.total" class="small muted">Showing up to 100 records of {{meta.total}}. The API supports pagination for larger datasets.</p></div></Transition><ConfirmDialog v-if="deleting" title="Delete this restaurant?" :text="deleting.name+' will be moved to Trash and can be restored.'" confirm-label="Delete" :busy="acting" @cancel="deleting=null" @confirm="remove"/><ConfirmDialog v-if="ask" :title="ask.title" :text="ask.text" confirm-label="Delete" :busy="acting" @cancel="ask=null" @confirm="confirmed"/></DashShell></template>

<style scoped>
.dashboard-restaurants{width:100%;max-width:100%;min-width:0;overflow:visible}
